create extension if not exists pgcrypto;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name varchar(60) unique not null,min_age int not null check(min_age>=0),max_age int not null check(max_age>=min_age),active boolean not null default true);
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name varchar(160),email varchar(255),role varchar(30) not null default 'operator' check(role in ('admin','coordinator','teacher','operator')),active boolean default true,created_at timestamptz default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),student_number varchar(30) unique not null,full_name varchar(160) not null,rg varchar(30),birth_date date not null,guardian_name varchar(160) not null,guardian_phone varchar(30),emergency_phone varchar(30),category_id uuid references public.categories(id),active boolean not null default true,notes text,public_qr_id uuid unique not null default gen_random_uuid(),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.trainings(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id),training_date date not null,start_time time not null,end_time time,teacher_id uuid references auth.users(id),location varchar(160),notes text,created_at timestamptz default now());
create table if not exists public.attendances(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id),training_id uuid not null references public.trainings(id),recorded_at timestamptz default now(),status varchar(20) not null check(status in ('PRESENT','ABSENT','JUSTIFIED','LATE')),method varchar(20) not null check(method in ('QR','MANUAL','SYNC')),recorded_by uuid references auth.users(id),client_event_id uuid unique,unique(student_id,training_id));
create or replace view public.attendance_report as select a.id,a.status,a.recorded_at,s.full_name,c.name category_name,t.training_date,t.start_time from public.attendances a join public.students s on s.id=a.student_id join public.trainings t on t.id=a.training_id left join public.categories c on c.id=s.category_id order by a.recorded_at desc;
alter table public.categories enable row level security; alter table public.profiles enable row level security; alter table public.students enable row level security; alter table public.trainings enable row level security; alter table public.attendances enable row level security;
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create policy "categories authenticated" on public.categories for select to authenticated using(true);
create policy "categories manager" on public.categories for all to authenticated using(public.my_role() in ('admin','coordinator')) with check(public.my_role() in ('admin','coordinator'));
create policy "profiles own" on public.profiles for select to authenticated using(id=auth.uid() or public.my_role()='admin');
create policy "profiles admin update" on public.profiles for update to authenticated using(public.my_role()='admin') with check(public.my_role()='admin');
create policy "students read auth" on public.students for select to authenticated using(true);
create policy "students write manager" on public.students for insert to authenticated with check(public.my_role() in ('admin','coordinator','operator'));
create policy "students update manager" on public.students for update to authenticated using(public.my_role() in ('admin','coordinator','operator')) with check(public.my_role() in ('admin','coordinator','operator'));
create policy "trainings read auth" on public.trainings for select to authenticated using(true);
create policy "trainings write manager" on public.trainings for all to authenticated using(public.my_role() in ('admin','coordinator','teacher')) with check(public.my_role() in ('admin','coordinator','teacher'));
create policy "attendance read auth" on public.attendances for select to authenticated using(true);
create policy "attendance insert auth" on public.attendances for insert to authenticated with check(public.my_role() in ('admin','coordinator','teacher','operator'));
create policy "attendance update manager" on public.attendances for update to authenticated using(public.my_role() in ('admin','coordinator','teacher')) with check(public.my_role() in ('admin','coordinator','teacher'));
insert into public.categories(name,min_age,max_age) values ('Sub-08',0,8),('Sub-10',9,10),('Sub-12',11,12),('Sub-14',13,14),('Sub-16',15,16) on conflict(name) do nothing;

create table if not exists public.student_documents(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,document_type varchar(60) not null,file_name varchar(255) not null,storage_path text,status varchar(30) default 'PENDENTE',created_at timestamptz default now(),created_by uuid references auth.users(id));
create table if not exists public.evaluations(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete cascade,evaluation_date date not null,speed_score numeric(5,2),technical_score numeric(5,2),physical_score numeric(5,2),tactical_score numeric(5,2),notes text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),title varchar(160) not null,message text not null,target_role varchar(30),target_student_id uuid references public.students(id),read_at timestamptz,created_at timestamptz default now());
create or replace view public.frequency_summary as select s.id,s.full_name,c.name category_name,count(distinct t.id) total_trainings,count(distinct case when a.status in ('PRESENT','LATE') then a.id end) present_count,case when count(distinct t.id)=0 then 0 else round(100.0*count(distinct case when a.status in ('PRESENT','LATE') then a.id end)/count(distinct t.id),1) end attendance_percent from public.students s left join public.categories c on c.id=s.category_id left join public.trainings t on (t.category_id=s.category_id or t.category_id is null) left join public.attendances a on a.student_id=s.id and a.training_id=t.id where s.active=true group by s.id,s.full_name,c.name;
alter table public.student_documents enable row level security; alter table public.evaluations enable row level security; alter table public.notifications enable row level security;
create policy "documents auth" on public.student_documents for select to authenticated using(true); create policy "documents write" on public.student_documents for all to authenticated using(public.my_role() in ('admin','coordinator','operator')) with check(public.my_role() in ('admin','coordinator','operator'));
create policy "eval read" on public.evaluations for select to authenticated using(true); create policy "eval write" on public.evaluations for all to authenticated using(public.my_role() in ('admin','coordinator','teacher')) with check(public.my_role() in ('admin','coordinator','teacher'));
create policy "notif read" on public.notifications for select to authenticated using(true); create policy "notif write" on public.notifications for all to authenticated using(public.my_role() in ('admin','coordinator')) with check(public.my_role() in ('admin','coordinator'));
